<h2>Calculate production throughput</h2><p class="lead">Measure finished output per unit of productive time and compare it with a target rate.</p><div class="notice">Use completed good units and the actual productive time window. Do not mix scheduled hours with runtime unless that is the definition you intend to track.</div><div class="form-grid"><div class="field"><label for="units">Good units completed</label><input id="units" type="number" value="1200" min="0" step="any"></div><div class="field"><label for="time">Productive time</label><input id="time" type="number" value="8" min="0.0001" step="any"></div><div class="field"><label for="unit">Time unit</label><select id="unit"><option value="hour" selected>hours</option><option value="minute">minutes</option><option value="day">days</option></select></div><div class="field"><label for="target">Target throughput per same time unit</label><input id="target" type="number" value="140" min="0" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Throughput rate</span><strong id="rate">—</strong></div><div class="metric"><span>Equivalent per hour</span><strong id="perhour">—</strong></div><div class="metric"><span>Gap to target</span><strong id="gap">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('rate').textContent='—';$('perhour').textContent='—';$('gap').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const u=num('units'),t=num('time'),target=num('target'),unit=$('unit').value;if(!(u>=0&&t>0&&target>=0))throw 0;const rate=u/t;const factor=unit==='minute'?60:unit==='day'?1/24:1;const ph=rate*factor;const gap=rate-target;$('rate').textContent=fmt(rate,2)+' units/'+unit;$('perhour').textContent=fmt(ph,2)+' units/hour';$('gap').textContent=(gap>=0?'+':'')+fmt(gap,2)+' units/'+unit;$('note').textContent='Throughput uses good completed output divided by the productive time window. Keep the time boundary consistent when comparing shifts or lines.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
